import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    points = []
    for i in range(n):
        x, y = data[1 + 2*i:3 + 2*i]
        points.append((x, y))
    incomparable = [0] * n
    for i, (x1, y1) in enumerate(points):
        mask = 1 << i
        for j, (x2, y2) in enumerate(points):
            if i != j and (x1 - x2) * (y1 - y2) < 0:
                mask |= 1 << j
        incomparable[i] = mask

    start = (1 << n) - 1
    seen = {start}
    stack = [start]
    while stack:
        state = stack.pop()
        bits = state
        while bits:
            b = bits & -bits
            bits -= b
            k = b.bit_length() - 1
            nxt = state & incomparable[k]
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    print(len(seen) % MOD)

if __name__ == '__main__':
    main()

