import sys

MOD = 998244353

data = list(map(int, sys.stdin.buffer.read().split()))
if not data:
    raise SystemExit
N, M = data[0], data[1]
conditions = data[2:]

# For each designated position X and left boundary l, record the
# smallest R among constraints with L >= l and designated position X.
best = [[N + 1] * (N + 2) for _ in range(N + 1)]
for i in range(M):
    L, R, X = conditions[3 * i:3 * i + 3]
    if R < best[X][L]:
        best[X][L] = R

for x in range(1, N + 1):
    for l in range(N, 0, -1):
        if best[x][l + 1] < best[x][l]:
            best[x][l] = best[x][l + 1]

# Binomial coefficients, used to interleave the value orders on either side
# of the maximum position.
C = [[0] * (N + 1) for _ in range(N + 1)]
for i in range(N + 1):
    C[i][0] = 1
    for j in range(1, i + 1):
        C[i][j] = (C[i - 1][j - 1] + (C[i - 1][j] if j < i else 0)) % MOD

# dp[l][r]: valid relative orders of positions in [l, r].
dp = [[0] * (N + 2) for _ in range(N + 2)]
for l in range(1, N + 2):
    dp[l][l - 1] = 1

for length in range(1, N + 1):
    for l in range(1, N - length + 2):
        r = l + length - 1
        total = 0
        for k in range(l, r + 1):
            # If a condition [L,R] with X=k is wholly inside this segment,
            # choosing k as its maximum would violate that condition.
            if best[k][l] <= r:
                continue
            total += C[length - 1][k - l] * dp[l][k - 1] * dp[k + 1][r]
        dp[l][r] = total % MOD

print(dp[1][N])

