import sys
from collections import defaultdict
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    values=data[1:]
    factors=[]
    primes=set()
    for value in values:
        x=value
        fs={}
        d=2
        while d*d<=x:
            if x%d==0:
                e=0
                while x%d==0:
                    x//=d
                    e+=1
                fs[d]=e
                primes.add(d)
            d+=1
        if x>1:
            fs[x]=1
            primes.add(x)
        factors.append(fs)

    answer=1
    for p in primes:
        dp={0:1}
        for t, fs in enumerate(factors, 1):
            k=fs.get(p,0)
            nd=defaultdict(int)
            for height, weight in dp.items():
                increments=(-k,k) if k else (0,)
                for inc in increments:
                    nh=height+inc
                    if nh>=0:
                        contribution=weight*pow(p,nh,MOD)
                        nd[nh]=(nd[nh]+contribution)%MOD
                    else:
                        # The new vertex establishes a lower minimum; all t
                        # previous normalized exponents increase by -nh.
                        contribution=weight*pow(p,-t*nh,MOD)
                        nd[0]=(nd[0]+contribution)%MOD
            dp=nd
        answer=answer*sum(dp.values())%MOD
    print(answer)

if __name__ == '__main__':
    main()

