import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    # The Grundy number of a is its number of prime factors, counted
    # with multiplicity.
    grundy = [0] * (limit + 1)
    for x in range(2, limit + 1):
        grundy[x] = grundy[x // spf[x]] + 1

    nim_sum = 0
    for x in values:
        nim_sum ^= grundy[x]

    print("Anna" if nim_sum else "Bruno")


if __name__ == "__main__":
    main()

