import sys
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    N,M,K=data[:3]
    A=data[3:]
    size=1<<20
    # f[x] = x^K, then Walsh transform gives character coefficients.
    f=[pow(x,K,MOD) for x in range(size)]
    h=1
    while h<size:
        step=h*2
        for i in range(0,size,step):
            for j in range(i,i+h):
                u=f[j]; v=f[j+h]
                f[j]=(u+v)%MOD
                f[j+h]=(u-v)%MOD
        h=step
    counts=[0]*size
    for a in A:
        for mask in range(size):
            counts[mask] += (mask&a).bit_count()&1
    # For each parity count c, signed subset count with size divisible by M.
    # Coefficients of (1+z)^(N-c)(1-z)^c are computed directly.
    # This implementation uses binomial residue DP per distinct c.
    distinct=set(counts)
    sums={}
    for c in distinct:
        dp=[0]*M
        dp[0]=1
        # multiply by N-c factors (1+z), then c factors (1-z)
        for _ in range(N-c):
            for r in range(M-1,-1,-1):
                dp[(r+1)%M]=(dp[(r+1)%M]+dp[r])%MOD
        for _ in range(c):
            for r in range(M-1,-1,-1):
                dp[(r+1)%M]=(dp[(r+1)%M]-dp[r])%MOD
        sums[c]=dp[0]
    ans=0
    for mask in range(size):
        ans=(ans+f[mask]*sums[counts[mask]])%MOD
    ans=ans*pow(size,MOD-2,MOD)%MOD
    print(ans)
if __name__=='__main__': main()

