import sys
from array import array

def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        n = next(data)
        q = next(data)
    except StopIteration:
        return

    parent = array('i', range(n))
    size = array('i', [1]) * n
    left = array('i', range(n))
    right = array('i', range(n))
    color = array('i', range(1, n + 1))
    count = array('i', [1]) * (n + 1)

    def find(x):
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != x:
            p = parent[x]
            parent[x] = r
            x = p
        return r

    def union(a, b):
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    out = []
    for _ in range(q):
        typ = next(data)
        if typ == 1:
            x = next(data) - 1
            c = next(data)
            r = find(x)
            old = color[r]
            if old != c:
                count[old] -= size[r]
                count[c] += size[r]
                color[r] = c

            if left[r] > 0:
                a = find(left[r] - 1)
                r = find(r)
                if color[a] == color[r]:
                    r = union(r, a)
            if right[r] + 1 < n:
                b = find(right[r] + 1)
                r = find(r)
                if color[b] == color[r]:
                    r = union(r, b)
        else:
            c = next(data)
            out.append(str(count[c]))

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

