from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y))
            at[b].append((a,i))
        best1=best2=0
        id1=-1
        gains=[0]*len(conflictingPairs)
        total=0
        for r in range(1,n+1):
            for a,i in at[r]:
                if a>best1:
                    best2=best1
                    best1=a
                    id1=i
                elif a>best2:
                    best2=a
            total += r-best1
            if id1>=0:
                gains[id1]+=best1-best2
        return total+max(gains, default=0)

