class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients C(a, b) modulo MOD.
        choose = [[0] * (n + 1) for _ in range(n + 1)]
        choose[0][0] = 1
        for a in range(1, n + 1):
            choose[a][0] = choose[a][a] = 1
            for b in range(1, a):
                choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD

        # If a number has t set bits, it takes 1 + steps(t) operations
        # to reach 1. (For t == 1, steps(t) == 0.)
        valid = [False] * (n + 1)
        for t in range(1, n + 1):
            x = t
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            valid[t] = steps < k

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # Put 0 here, then choose the remaining set-bit positions.
                for total_ones in range(1, n + 1):
                    if valid[total_ones]:
                        need = total_ones - prefix_ones
                        if 0 <= need <= remaining:
                            answer += choose[remaining][need]
                prefix_ones += 1

        return answer % MOD

