import sys
from collections import deque

def solve():
    input=sys.stdin.buffer.readline
    n=int(input())
    g=[input().strip().decode() for _ in range(n)]
    # outgoing/incoming grouped by character
    out=[[[] for _ in range(26)] for _ in range(n)]
    inc=[[[] for _ in range(26)] for _ in range(n)]
    dist=[[-1]*n for _ in range(n)]
    q=deque()
    for i in range(n):
        dist[i][i]=0
        q.append((i,i))
    for i in range(n):
        for j,c in enumerate(g[i]):
            if c!='-':
                k=ord(c)-97
                out[i][k].append(j)
                inc[j][k].append(i)
                if dist[i][j]<0:
                    dist[i][j]=1
                    q.append((i,j))
    while q:
        u,v=q.popleft()
        nd=dist[u][v]+2
        for k in range(26):
            left=inc[u][k]
            right=out[v][k]
            if left and right:
                for a in left:
                    row=dist[a]
                    for b in right:
                        if row[b]<0:
                            row[b]=nd
                            q.append((a,b))
    print('\n'.join(' '.join(map(str,row)) for row in dist))

solve()

