import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    u = vals[::2]
    d = vals[1::2]

    max_h = min(a + b for a, b in zip(u, d))

    def feasible(h):
        low = max(0, h - d[0])
        high = min(u[0], h)
        if low > high:
            return False
        for i in range(1, n):
            next_low = max(0, h - d[i])
            next_high = min(u[i], h)
            low = max(next_low, low - x)
            high = min(next_high, high + x)
            if low > high:
                return False
        return True

    left, right = 0, max_h
    while left < right:
        mid = (left + right + 1) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid - 1

    print(sum(a + b for a, b in zip(u, d)) - n * left)

if __name__ == '__main__':
    main()

