import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    k = 2
    for _ in range(m):
        u = data[k] - 1
        v = data[k + 1] - 1
        k += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Gauss-Jordan elimination over GF(2).
    rank = 0
    pivots = []
    for col in range(n):
        pivot_row = next((r for r in range(rank, n) if (rows[r] >> col) & 1), None)
        if pivot_row is None:
            continue
        rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]
        for r in range(n):
            if r != rank and ((rows[r] >> col) & 1):
                rows[r] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    labels = [0] * n

    # Each nullspace basis vector gets its own bit in the output labels.
    for bit, free_col in enumerate(free_cols):
        vector = 1 << free_col
        for row, pivot_col in enumerate(pivots):
            if (rows[row] >> free_col) & 1:
                vector |= 1 << pivot_col
        for v in range(n):
            if (vector >> v) & 1:
                labels[v] |= 1 << bit

    if any(value == 0 for value in labels):
        print("No")
    else:
        print("Yes")
        print(*labels)

if __name__ == "__main__":
    main()

