import math

N = int(sys.stdin.readline())

# Since N = (x-y)(x^2+xy+y^2) >= (x-y)^3, d=x-y <= cubert(N).
limit = 1
while (limit + 1) ** 3 <= N:
    limit += 1

for d in range(1, limit + 1):
    if N % d:
        continue
    # N/d = 3*y^2 + 3*d*y + d^2.
    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root != disc or (root - 3 * d) % 6:
        continue
    y = (root - 3 * d) // 6
    if y > 0:
        print(y + d, y)
        break
else:
    print(-1)

