from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order in matrix coordinates: SE, SW, NW, NE.
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))
        size = n * m
        # Memoize future path length, indexed by cell, direction, turn-used, expected value.
        memo = array('H', [65535]) * (size * 16)

        def extend(r, c, d, turned, need):
            cell = r * m + c
            idx = cell * 16 + d * 4 + int(turned) * 2 + (0 if need == 2 else 1)
            cached = memo[idx]
            if cached != 65535:
                return cached

            best = 0
            next_dirs = (d,) if turned else (d, (d + 1) % 4)
            next_need = 0 if need == 2 else 2
            for nd in next_dirs:
                dr, dc = dirs[nd]
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == need:
                    best = max(best, 1 + extend(nr, nc, nd, turned or nd != d, next_need))
            memo[idx] = best
            return best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    for d in range(4):
                        answer = max(answer, 1 + extend(r, c, d, False, 2))
        return answer

