from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        nums = list(range(1, n + 1))
        odd = (n + 1) // 2
        even = n // 2

        def ways(rem_odd: int, rem_even: int, length: int, next_parity: int) -> int:
            if length == 0:
                return 1 if rem_odd == 0 and rem_even == 0 else 0
            odd_need = (length + 1) // 2 if next_parity == 1 else length // 2
            even_need = length - odd_need
            if rem_odd != odd_need or rem_even != even_need:
                return 0
            return math.factorial(rem_odd) * math.factorial(rem_even)

        total = 0
        for x in nums:
            if x % 2:
                total += ways(odd - 1, even, n - 1, 0)
            else:
                total += ways(odd, even - 1, n - 1, 1)
        if k > total:
            return []

        ans = []
        prev = None
        while nums:
            chosen = None
            for x in nums:
                p = x % 2
                if prev is not None and p == prev:
                    continue
                rem_odd = odd - (p == 1)
                rem_even = even - (p == 0)
                count = ways(rem_odd, rem_even, len(nums) - 1, 1 - p)
                if k > count:
                    k -= count
                else:
                    chosen = x
                    odd, even = rem_odd, rem_even
                    prev = p
                    ans.append(x)
                    nums.remove(x)
                    break
            if chosen is None:
                return []
        return ans

