class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            a = pow(10, i, k)
            if n - 1 - i == i:
                coeff.append(a)
            else:
                coeff.append((a + pow(10, n - 1 - i, k)) % k)

        # suffix[i][r] indicates whether positions i..m-1 can contribute
        # a total residue r modulo k.
        suffix = [[False] * k for _ in range(m + 1)]
        suffix[m][0] = True
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            nxt, cur = suffix[i + 1], suffix[i]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        cur[r] = True
                        break

        # Greedily fix each digit of the first half, retaining feasibility.
        half = []
        rem = 0
        for i, c in enumerate(coeff):
            for d in range(9, -1, -1):
                if i == 0 and d == 0:
                    continue
                nr = (rem + d * c) % k
                if suffix[i + 1][(-nr) % k]:
                    half.append(str(d))
                    rem = nr
                    break

        h = ''.join(half)
        return h + (h[:-1][::-1] if n % 2 else h[::-1])

