    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w)); g[v].append((u,w))
        parent = [-1]*n
        order = [0]
        parent[0] = 0
        pw = [0]*n
        for u in order:
            for v,w in g[u]:
                if parent[v] == -1:
                    parent[v] = u; pw[v] = w; order.append(v)
        f0 = [0]*n
        f1 = [0]*n
        for u in reversed(order):
            base = 0
            gains = []
            for v,w in g[u]:
                if parent[v] == u:
                    base += f0[v]
                    gains.append(w + f1[v] - f0[v])
            gains.sort(reverse=True)
