        from bisect import bisect_left, bisect_right

        a, rest = p.split('*', 1)
        b, c = rest.split('*', 1)

        def occurrences(t):
            if not t:
                return []
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                    pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                    if j == m:
                        out.append(i - m + 1)
                        j = pi[j - 1]
            return out

        if not a and not b and not c:
            return 0

