            if not a:
                return len(c) if occurrences(c) else -1
            if not c:
                return len(a) if occurrences(a) else -1
            aa, cc = occurrences(a), occurrences(c)
            best = len(s) + 1
            for x in aa:
                j = bisect_left(cc, x + len(a))
                if j < len(cc):
                    best = min(best, cc[j] + len(c) - x)
            return best if best <= len(s) else -1

        bb = occurrences(b)
        if not bb:
            return -1
        aa = occurrences(a) if a else []
        cc = occurrences(c) if c else []
        best = len(s) + 1
        for y in bb:
            be = y + len(b)
            if a:
                i = bisect_right(aa, y - len(a)) - 1
                if i < 0:
                    continue
                start = aa[i]
            else:
                start = y
            if c:
                j = bisect_left(cc, be)
                if j == len(cc):
                    continue
                end = cc[j] + len(c)
            else:
                end = be
            best = min(best, end - start)
        return best if best <= len(s) else -1

