import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x = data[p] - 1
        y = data[p + 1] - 1
        z = data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n

    for start in range(n):
        if potential[start] != -1:
            continue

        potential[start] = 0
        queue = [start]
        component = []

        for v in queue:
            component.append(v)
            for u, z in graph[v]:
                expected = potential[v] ^ z
                if potential[u] == -1:
                    potential[u] = expected
                    queue.append(u)
                elif potential[u] != expected:
                    print(-1)
                    return

        root_value = 0
        for bit in range(30):
            ones = sum((potential[v] >> bit) & 1 for v in component)
            if ones * 2 > len(component):
                root_value |= 1 << bit

        for v in component:
            answer[v] = potential[v] ^ root_value

    print(*answer)

if __name__ == "__main__":
    main()

