from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for node in range(1, n):
            children[parent[node]].append(node)

        start = [0] * n
        end = [0] * n
        postorder = []
        stack = [(0, False)]

        while stack:
            node, exiting = stack.pop()
            if not exiting:
                start[node] = len(postorder)
                stack.append((node, True))
                for child in reversed(children[node]):
                    stack.append((child, False))
            else:
                postorder.append(node)
                end[node] = len(postorder)

        prefix = [0]
        for node in postorder:
            prefix.append(prefix[-1] ^ (1 << (ord(s[node]) - ord('a'))))

        answer = [False] * n
        for node in range(n):
            parity = prefix[end[node]] ^ prefix[start[node]]
            answer[node] = parity.bit_count() <= 1
        return answer

