class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        # Best totals ending with A/B at the previous hour, and two hours back.
        a_prev, b_prev = energyDrinkA[0], energyDrinkB[0]
        a_two_back = b_two_back = 0

        for i in range(1, len(energyDrinkA)):
            a_now = energyDrinkA[i] + max(a_prev, b_two_back)
            b_now = energyDrinkB[i] + max(b_prev, a_two_back)

            a_two_back, b_two_back = a_prev, b_prev
            a_prev, b_prev = a_now, b_now

        return max(a_prev, b_prev)

