class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        for _ in range(t):
            next_counts = [0] * 26
            for i in range(25):
                next_counts[i + 1] = counts[i]
            # Each 'z' produces both 'a' and 'b'.
            next_counts[0] = counts[25]
            next_counts[1] = (next_counts[1] + counts[25]) % MOD
            counts = next_counts

        return sum(counts) % MOD

