class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        inf = 10**30
        dist = {n: n}  # The initial value is included in the total cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if dist.get(value) != cost:
                continue
            if value == m:
                return cost

            digits = str(value)
            for i, char in enumerate(digits):
                digit = int(char)
                place = 10 ** (len(digits) - 1 - i)
                for new_digit in (digit - 1, digit + 1):
                    if 0 <= new_digit <= 9:
                        nxt = value + (new_digit - digit) * place
                        if is_prime[nxt]:
                            continue
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, inf):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

