from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # For each first split position i, build LCP(i, j) for all j > i.
        # The recurrence uses the row for i+1, so only O(n) extra space is needed.
        answer = 0
        next_row = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            row = [0] * (n + 1)
            first_is_prefix = z[i] >= i
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    row[j] = next_row[j + 1] + 1

                # nums[i:j] is a prefix of nums[j:] iff LCP(i, j) >= j-i.
                second_is_prefix = row[j] >= j - i
                # nums[:i] is a prefix of nums[i:j] iff its length fits and matches.
                if second_is_prefix or (first_is_prefix and j >= 2 * i):
                    answer += 1
            next_row = row

        return answer

