class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        n = len(word)
        answer = 0

        for left in range(n):
            seen = {v: 0 for v in vowels}
            consonants = 0

            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    seen[ch] += 1
                else:
                    consonants += 1
                    if consonants > k:
                        break

                if consonants == k and all(seen[v] > 0 for v in vowels):
                    answer += 1

        return answer

